public class FinanceFontResolver:IFontResolver {
 public FontResolverInfo ResolveTypeface(string familyName,bool bold,bool italic)=>new(bold?"FinanceBold":"FinanceRegular");
 public byte[] GetFont(string faceName){using var stream=typeof(FinanceFontResolver).Assembly.GetManifestResourceStream("Society.Api.Fonts."+(faceName=="FinanceBold"?"VeraBd.ttf":"Vera.ttf"))??throw new InvalidOperationException("Embedded finance font missing");using var output=new MemoryStream();stream.CopyTo(output);return output.ToArray();}
}
public class FinanceDocuments(AppDb db,IObjectStore store){
 static readonly object fontLock=new(); public static void Initialize(){lock(fontLock){GlobalFontSettings.FontResolver??=new FinanceFontResolver();}}
 public byte[] Render(string title,string subtitle,IEnumerable<(string label,string value)> values,string? footer=null){Initialize();using var pdf=new PdfDocument();pdf.Info.Title=title;pdf.Info.Author="Assemblia";PdfPage page=null!;XGraphics graphics=null!;double y=0;var normal=new XFont("Finance",9);var bold=new XFont("Finance",10,XFontStyleEx.Bold);var heading=new XFont("Finance",25,XFontStyleEx.Bold);var small=new XFont("Finance",8);var green=XColor.FromArgb(25,102,79);void NewPage(){graphics?.Dispose();page=pdf.AddPage();page.Size=PdfSharp.PageSize.A4;graphics=XGraphics.FromPdfPage(page);graphics.DrawRectangle(new XSolidBrush(green),0,0,page.Width.Point,8);graphics.DrawString("Assemblia",bold,new XSolidBrush(green),42,44);graphics.DrawString(title,heading,XBrushes.Black,new XRect(42,67,page.Width.Point-84,34),XStringFormats.TopLeft);y=122;foreach(var line in Wrap(subtitle,94)){graphics.DrawString(line,small,XBrushes.Gray,42,y);y+=12;}y+=20;graphics.DrawLine(new XPen(XColors.LightGray,.5),42,y,page.Width.Point-42,y);y+=22;}
 NewPage();foreach(var (label,value) in values){var chunks=Wrap(value,85).ToArray();if(y+Math.Min(chunks.Length,40)*13+28>page.Height.Point-66)NewPage();if(!string.IsNullOrEmpty(label)){graphics.DrawString(label.ToUpperInvariant(),small,new XSolidBrush(green),42,y);y+=15;}foreach(var line in chunks){if(y>page.Height.Point-66)NewPage();graphics.DrawString(line,normal,XBrushes.Black,42,y);y+=13;}y+=13;}graphics.Dispose();for(var n=0;n<pdf.PageCount;n++){using var g=XGraphics.FromPdfPage(pdf.Pages[n],XGraphicsPdfPageOptions.Append);g.DrawLine(new XPen(XColors.LightGray,.5),42,pdf.Pages[n].Height.Point-42,pdf.Pages[n].Width.Point-42,pdf.Pages[n].Height.Point-42);g.DrawString((footer??"Financial record • Generated from authorized source records")+"  |  "+(n+1)+" / "+pdf.PageCount,small,XBrushes.Gray,new XRect(42,pdf.Pages[n].Height.Point-31,pdf.Pages[n].Width.Point-84,14),XStringFormats.TopLeft);}using var output=new MemoryStream();pdf.Save(output,false);return output.ToArray();}
 static IEnumerable<string> Wrap(string text,int width){foreach(var paragraph in (text??"").Replace("\r","").Split('\n')){if(paragraph.Length==0){yield return "";continue;}var remaining=paragraph;while(remaining.Length>width){var cut=remaining.LastIndexOf(' ',width);if(cut<width/3)cut=width;yield return remaining[..cut];remaining=remaining[cut..].TrimStart();}yield return remaining;}}
 public async Task<Guid> Generate(Guid tenant,string kind,Guid id,CancellationToken ct=default){Guid entity;Guid? unit;byte[] bytes;Guid? existing;
 if(kind=="Invoice"){var i=await db.Set<FinanceInvoice>().SingleAsync(i=>i.TenantId==tenant&&i.Id==id,ct);if(i.Status!="Issued")throw new DomainException("Only issued invoices and credit notes have official documents");existing=i.DocumentId;if(existing!=null)return existing.Value;entity=i.EntityId;unit=i.UnitId;var issuer=JsonSerializer.Deserialize<JsonElement>(i.IssuerSnapshot);var data=new List<(string,string)>{("Issuer",issuer.GetProperty("LegalName").GetString()+"\n"+issuer.GetProperty("Address").GetString()),("Tax registration",string.IsNullOrWhiteSpace(issuer.GetProperty("TaxRegistration").GetString())?"Not configured":issuer.GetProperty("TaxRegistration").GetString()!),("Bill to",i.CounterpartyName+"\n"+i.CounterpartyAddress),("Document",i.Number+"  |  Issued "+i.Date.ToString("dd MMM yyyy")+"  |  Due "+i.DueOn.ToString("dd MMM yyyy"))};var rows=JsonSerializer.Deserialize<JsonElement[]>(i.Lines)!;foreach(var line in rows){var description=line.TryGetProperty("Description",out var d)?d.GetString()??"":"Line";var amount=line.TryGetProperty("total",out var v)?v.GetDecimal():line.GetProperty("Quantity").GetDecimal()*line.GetProperty("UnitPrice").GetDecimal();data.Add((description,i.Currency+" "+amount.ToString("N"+FinanceService.Currencies[i.Currency],System.Globalization.CultureInfo.InvariantCulture)));}string Amount(decimal value)=>value.ToString("N"+FinanceService.Currencies[i.Currency],System.Globalization.CultureInfo.InvariantCulture);data.Add(("Summary","Subtotal: "+i.Currency+" "+Amount(i.Subtotal)+"\nDiscount: "+Amount(i.Discount)+"\nTax: "+Amount(i.Tax)+"\nTOTAL: "+i.Currency+" "+Amount(i.Total)));if(i.OriginalId!=null)data.Add(("Original document",await db.Set<FinanceInvoice>().Where(x=>x.Id==i.OriginalId).Select(x=>x.Number).SingleAsync(ct)));if(i.Notes!="")data.Add(("Notes",i.Notes));data.Add(("Reference",i.Id.ToString()));bytes=Render(i.Kind=="Credit"?"Credit note":"Invoice",i.Purpose,data,"Issued historical document • Payment status is maintained separately");var file=await Save(tenant,entity,unit,id,"Invoice",i.Number+".pdf",bytes,ct);i.DocumentId=file;await db.SaveChangesAsync(ct);return file;}
 else if(kind=="Receipt"){var r=await db.Set<FinanceReceipt>().SingleAsync(r=>r.TenantId==tenant&&r.Id==id,ct);if(r.DocumentId!=null)return r.DocumentId.Value;var p=await db.Set<FinancePayment>().SingleAsync(p=>p.TenantId==tenant&&p.Id==r.PaymentId&&p.Status=="Confirmed",ct);var snapshot=JsonSerializer.Deserialize<JsonElement>(r.Snapshot);var values=new List<(string,string)>{("Received by",snapshot.GetProperty("LegalName").GetString()+"\n"+snapshot.GetProperty("Address").GetString()),("Receipt",r.Number+"  |  "+snapshot.GetProperty("Date").GetString()),("Received from",snapshot.GetProperty("Payer").GetString()??""),("Amount received",r.Currency+" "+r.Amount.ToString("N"+FinanceService.Currencies[r.Currency],System.Globalization.CultureInfo.InvariantCulture)),("Payment method",snapshot.GetProperty("Method").GetString()??""),("Confirmed reference",snapshot.GetProperty("Reference").GetString()??""),("Important","This receipt records confirmed collection. Unapplied amounts remain advances. Subsequent refunds and invoice allocations are shown in the live statement. No tax-deductibility representation is made."),("Internal reference",p.Id.ToString())};bytes=Render("Payment receipt","Confirmed collection • "+r.Number,values);var file=await Save(tenant,r.EntityId,r.UnitId,r.Id,"Receipt",r.Number+".pdf",bytes,ct);r.DocumentId=file;await db.SaveChangesAsync(ct);return file;}
 throw new DomainException("Unknown financial document kind");}
 async Task<Guid> Save(Guid tenant,Guid entity,Guid? unit,Guid resource,string kind,string name,byte[] bytes,CancellationToken ct){var file=new FinanceFile{TenantId=tenant,EntityId=entity,UnitId=unit,ResourceId=resource,Kind=kind,Name=name,Length=bytes.Length,ContentType="application/pdf"};await store.Put(tenant,file.Id,bytes);db.Add(file);await db.SaveChangesAsync(ct);return file.Id;}
}
public static partial class FinanceEndpoints {
 static void MapDocuments(RouteGroupBuilder t){
 t.MapPost("/invoices/{id:guid}/document",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s)=>{var invoice=await s.Invoice(tenant,id);if(invoice.Status!="Issued")throw new DomainException("Issue the invoice before generating its official PDF");return await QueueDocument(tenant,invoice.EntityId,invoice.UnitId!.Value,"Invoice",id,a.UserId,db);});
 t.MapPost("/receipts/{id:guid}/document",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s)=>{var receipt=await db.Set<FinanceReceipt>().SingleOrDefaultAsync(r=>r.TenantId==tenant&&r.Id==id)??throw new AccessDeniedException();await ReceiptAccess(receipt,db,a,s);return await QueueDocument(tenant,receipt.EntityId,receipt.UnitId!.Value,"Receipt",id,a.UserId,db);});
 t.MapGet("/invoices/{id:guid}/pdf",async(Guid tenant,Guid id,AppDb db,FinanceService s,FinanceDocuments documents,IObjectStore store)=>{var invoice=await s.Invoice(tenant,id);await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var file=await documents.Generate(tenant,"Invoice",id);await tx.CommitAsync();return Results.File(store.Open(tenant,file),"application/pdf",invoice.Number+".pdf");});
 t.MapGet("/receipts/{id:guid}/pdf",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s,FinanceDocuments documents,IObjectStore store)=>{var receipt=await db.Set<FinanceReceipt>().SingleOrDefaultAsync(r=>r.TenantId==tenant&&r.Id==id)??throw new AccessDeniedException();await ReceiptAccess(receipt,db,a,s);await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var file=await documents.Generate(tenant,"Receipt",id);await tx.CommitAsync();return Results.File(store.Open(tenant,file),"application/pdf",receipt.Number+".pdf");});
 t.MapPost("/reports/export",async(Guid tenant,ReportJob r,AppDb db,Access a,FinanceService s)=>{await s.Require(tenant,r.EntityId,r.UnitId,"finance.export");if(!ReportNames.Contains(r.Report)||r.Format is not("pdf" or "csv" or "xlsx"))throw new DomainException("Choose a report and PDF, CSV or Excel format");var job=new FinanceJob{TenantId=tenant,EntityId=r.EntityId,UnitId=r.UnitId,AuthorId=a.UserId,Kind="Report",Key="export:"+Guid.NewGuid(),Payload=JsonSerializer.Serialize(r)};db.Add(job);a.Audit(tenant,"finance.export.requested",job.Id,new{r.Report,r.Format});await db.SaveChangesAsync();return Results.Ok(job);});
 t.MapGet("/jobs/{id:guid}/download",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s,IObjectStore store)=>{var job=await db.Set<FinanceJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.Id==id&&j.State=="Completed"&&j.DocumentId!=null)??throw new AccessDeniedException();if(job.AuthorId!=a.UserId)throw new AccessDeniedException();await s.Require(tenant,job.EntityId,job.UnitId,"finance.export");var exported=JsonSerializer.Deserialize<ReportJob>(job.Payload)!;if(exported.Report=="Reconciliation")await s.Require(tenant,job.EntityId,job.UnitId,"finance.reconcile");var file=await db.Set<FinanceFile>().SingleAsync(f=>f.Id==job.DocumentId&&f.TenantId==tenant);a.Audit(tenant,"finance.export.downloaded",id);await db.SaveChangesAsync();return Results.File(store.Open(tenant,file.Id),file.ContentType,file.Name);});
 }
 static async Task<IResult> QueueDocument(Guid tenant,Guid entity,Guid unit,string kind,Guid id,Guid author,AppDb db){var key="document:"+kind+":"+id;var existing=await db.Set<FinanceJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.EntityId==entity&&j.Key==key);if(existing!=null)return Results.Ok(existing);var job=new FinanceJob{TenantId=tenant,EntityId=entity,UnitId=unit,Kind="Document",AuthorId=author,Key=key,Payload=JsonSerializer.Serialize(new DocumentJob(kind,id))};db.Add(job);await db.SaveChangesAsync();return Results.Ok(job);}
 public static async Task ReceiptAccess(FinanceReceipt r,AppDb db,Access a,FinanceService s){await a.Member(r.TenantId);var p=await db.Set<FinancePayment>().SingleAsync(p=>p.TenantId==r.TenantId&&p.Id==r.PaymentId);if(p.MembershipId!=null&&await db.Memberships.AnyAsync(m=>m.Id==p.MembershipId&&m.TenantId==r.TenantId&&MembershipExperience.Owned(db,a.UserId,true).Select(own=>own.Id).Contains(m.Id)))return;if(await db.Set<PaymentIntent>().AnyAsync(i=>i.TenantId==r.TenantId&&i.PaymentId==p.Id&&i.UserId==a.UserId))return;await s.Require(r.TenantId,r.EntityId,r.UnitId);}
 public static Task<object> ExportReport(Guid tenant,ReportJob r,int page,AppDb db,Access a,FinanceService s)=>Report(tenant,r.Report,r.EntityId,r.UnitId,r.MemberId,r.ChapterId,r.EventId,r.From,r.To,page,db,a,s);
}
public static class FinanceExport {
 public static readonly JsonSerializerOptions Web=new(JsonSerializerDefaults.Web);
 public static JsonElement Summary(JsonElement b)=>JsonSerializer.SerializeToElement(new{recordType="Opening and closing summary",entityId=b.GetProperty("entityId").GetGuid(),currency=b.GetProperty("currency").GetString(),opening=b.GetProperty("opening").GetDecimal(),charges=b.GetProperty("charges").GetDecimal(),creditsAndAllocations=b.GetProperty("creditsAndAllocations").GetDecimal(),closing=b.GetProperty("closing").GetDecimal()});
 public static async Task<byte[]> Build(Guid tenant,ReportJob request,AppDb db,Access a,FinanceService s,FinanceDocuments pdf,CancellationToken ct){var rows=new List<JsonElement>();for(var page=1;page<=2001;page++){if(page>2000)throw new DomainException("Narrow this export to at most 200,000 source rows");var result=JsonSerializer.SerializeToElement(await FinanceEndpoints.ExportReport(tenant,request,page,db,a,s),Web);if(!result.TryGetProperty("items",out var items))break;if(result.TryGetProperty("truncated",out var truncated)&&truncated.GetBoolean())throw new DomainException("Narrow this statement range before export; its source view exceeds 1,000 entries");var batch=items.EnumerateArray().ToArray();if(page==1&&result.TryGetProperty("balances",out var balances))rows.AddRange(balances.EnumerateArray().Select(Summary));rows.AddRange(batch);if(request.Format=="pdf"&&rows.Count>5000)throw new DomainException("PDF export is limited to 5,000 source rows; choose CSV or Excel for larger reports");if(!result.TryGetProperty("total",out var total)||rows.Count>=total.GetInt32()||batch.Length==0)break;}return Encode(request.Report,request.Format,rows,pdf);}
 public static byte[] Encode(string title,string format,IReadOnlyList<JsonElement> rows,FinanceDocuments pdf){var headers=rows.SelectMany(r=>r.ValueKind==JsonValueKind.Object?r.EnumerateObject().Select(p=>p.Name):[]).Distinct().ToArray();string Value(JsonElement row,string key)=>row.TryGetProperty(key,out var v)?v.ValueKind==JsonValueKind.String?v.GetString()??"":v.ToString():"";if(format=="pdf")return pdf.Render(title,"Authorized financial export • Values remain separated by entity and currency",rows.SelectMany((r,i)=>headers.Select(h=>((i+1)+" · "+h,Value(r,h)))));if(format=="csv"){string Cell(string value){if(value.TrimStart().Length>0&&"=+-@".Contains(value.TrimStart()[0]))value="'"+value;return "\""+value.Replace("\"","\"\"")+"\"";}return new UTF8Encoding(true).GetPreamble().Concat(Encoding.UTF8.GetBytes(string.Join(",",headers.Select(Cell))+"\r\n"+string.Join("\r\n",rows.Select(r=>string.Join(",",headers.Select(h=>Cell(Value(r,h)))))))).ToArray();}using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true)){void File(string path,string body){using var writer=new StreamWriter(zip.CreateEntry(path).Open(),new UTF8Encoding(false));writer.Write(body);}File("[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");File("_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");File("xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Finance\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");File("xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/></Relationships>");using var sheet=zip.CreateEntry("xl/worksheets/sheet1.xml").Open();using var xml=XmlWriter.Create(sheet,new XmlWriterSettings{Encoding=new UTF8Encoding(false)});xml.WriteStartDocument();xml.WriteStartElement("worksheet","http://schemas.openxmlformats.org/spreadsheetml/2006/main");xml.WriteStartElement("sheetData");foreach(var row in new[]{headers}.Concat(rows.Select(r=>headers.Select(h=>Value(r,h)).ToArray()))){xml.WriteStartElement("row");foreach(var value in row){xml.WriteStartElement("c");xml.WriteAttributeString("t","inlineStr");xml.WriteStartElement("is");xml.WriteElementString("t",value);xml.WriteEndElement();xml.WriteEndElement();}xml.WriteEndElement();}xml.WriteEndElement();xml.WriteEndElement();xml.WriteEndDocument();}return output.ToArray();}
}
